using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

/// <summary>Simulates web search results for a given query.</summary>
[Description("Search the web for information on a topic. Returns a list of relevant results.")]
static string WebSearch([Description("The search query")] string query)
{
    Console.WriteLine($"  [Tool] WebSearch: \"{query}\"");

    // Simulated search results for demonstration purposes.
    var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
    {
        ["AI agents"] = [
            "AI agents are autonomous software entities that perceive their environment and take actions to achieve goals. They use LLMs for reasoning and can leverage tools to interact with external systems.",
            "Modern AI agents combine planning, memory, and tool use. Popular frameworks include AutoGen, Semantic Kernel, and LangChain.",
            "Key challenges for AI agents include hallucination, reliability, and safe tool execution in production environments."
        ],
        ["machine learning 2026"] = [
            "In 2026, foundation models have become multimodal by default, handling text, images, audio, and video in unified architectures.",
            "Edge AI deployment has accelerated with on-device models running efficiently on consumer hardware.",
            "Reinforcement learning from human feedback (RLHF) has evolved into constitutional AI approaches for safer model alignment."
        ]
    };

    // Return matching results or a generic response
    foreach (var (key, value) in results)
    {
        if (query.Contains(key, StringComparison.OrdinalIgnoreCase))
            return string.Join("\n\n", value);
    }

    return $"Search results for '{query}': Recent developments indicate significant progress in this area with multiple industry applications and ongoing academic research.";
}

/// <summary>Stores a research note for later summarization.</summary>
[Description("Save a research note. Use this to record key findings during research.")]
static string TakeNote([Description("The note content to save")] string note)
{
    Console.WriteLine($"  [Tool] TakeNote: \"{note[..Math.Min(note.Length, 80)]}...\"");
    ResearchNotes.Notes.Add(note);
    return $"Note saved. Total notes: {ResearchNotes.Notes.Count}";
}

/// <summary>Retrieves all saved research notes.</summary>
[Description("Retrieve all saved research notes to review findings before summarizing.")]
static string GetNotes()
{
    Console.WriteLine("  [Tool] GetNotes");
    if (ResearchNotes.Notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n---\n", ResearchNotes.Notes.Select((n, i) => $"[{i + 1}] {n}"));
}

// --- Main Agent Logic ---

Console.WriteLine("=== Research Agent ===\n");

var topic = args.Length > 0 ? string.Join(' ', args) : "AI agents";
Console.WriteLine($"Research topic: {topic}\n");

// Configure the AI client with function-calling tools
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "demo-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(model).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your task is to research a given topic thoroughly, then provide a clear summary.

        Follow this process:
        1. Search the web for information on the topic (try 2-3 different search queries)
        2. Take notes on the most important findings
        3. Review your notes
        4. Provide a final comprehensive summary to the user

        Always use your tools - search first, take notes on key findings, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Agent Summary ===\n");
Console.WriteLine(response.Text);

if (ResearchNotes.Notes.Count > 0)
{
    Console.WriteLine($"\n[Research completed with {ResearchNotes.Notes.Count} notes taken]");
}

// Static class to hold notes across tool invocations
static class ResearchNotes
{
    public static List<string> Notes { get; } = [];
}

